def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # The 8s make vertical rails. The 2 draws a continuous route through the
    # openings, joining neighboring rails on the row containing each opening.
    bars=[c for c in range(w) if sum(row[c]==8 for row in g)>=2]
    mr,mc=next(((r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==2),(0,0))
    # In the demos the route follows each rail gap, with horizontal turns at
    # the gap row, and vertical continuation in the chosen rail column.
    # Build the route from connected empty cells, using the initial 2 as seed.
    from collections import deque
    seen={(mr,mc)}; q=deque([(mr,mc)])
    while q:
        r,c=q.popleft()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=rr<h and 0<=cc<w and g[rr][cc]!=8 and (rr,cc) not in seen:
                # move only along rows/columns of obstacle structure; unconstrained
                if rr==r or cc==c:
                    seen.add((rr,cc));q.append((rr,cc))
    # Not a generic flood: draw colored route in free columns aligned with rail gaps.
    # Select rows adjacent to rail gaps and connect their nearest consecutive rail columns.
    gaps={c:[r for r in range(h) if g[r][c]==0 and any(g[x][c]==8 for x in range(h))] for c in bars}
    for c,rs in gaps.items():
        for r in rs:
            # color gap and extend vertical path up/down only where no 8 obstacle
            g[r][c]=2
    # At each gap row, connect to adjacent rail gap in that row when it forms route.
    for r in range(h):
        cols=[c for c in bars if g[r][c]==2]
        if len(cols)>1:
            for c in range(min(cols),max(cols)+1):
                if g[r][c]==0:g[r][c]=2
    return g
